WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) event_seq, SUM(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_quantity FROM inventory) SELECT s.id, s.store_id, s.product_id, s.quantity, s.last_restock, s.cumulative_quantity, (SELECT SUM(t2.units) FROM store_sales t2 WHERE t2.product_id = s.product_id) AS sum_store_sale_units FROM with_windows s ORDER BY cumulative_quantity NULLS FIRST
